34	if (!function_exists('inside_board_manage')) {
35	    function inside_board_manage(int $boardNo): ?array
36	    {
37	        static $cache = [];
38	
39	        if (array_key_exists($boardNo, $cache)) {
40	            return $cache[$boardNo];
41	        }
42	
43	        $db = DB::getInstance();
44	        $stmt = $db->prepare(
45	            'SELECT no, sitekey, title, list_size, category_yn, view_yn
46	             FROM nb_board_manage
47	             WHERE no = :no AND sitekey = :sitekey
48	             LIMIT 1'
49	        );
50	        $stmt->execute([':no' => $boardNo, ':sitekey' => inside_board_sitekey()]);
51	        $row = $stmt->fetch(PDO::FETCH_ASSOC);
