90	if (!function_exists('inside_board_list')) {
91	    /**
92	     * @return array{rows: list<array<string,mixed>>, totalRows: int, totalPages: int, page: int, perPage: int}
93	     */
94	    function inside_board_list(int $boardNo, int $page, ?int $categoryNo = null, ?string $q = null): array
95	    {
96	        $sitekey = inside_board_sitekey();
97	        $perPage = inside_board_per_page($boardNo);
98	        $page = max(1, $page);
99	        $offset = ($page - 1) * $perPage;
100	
101	        $where = 'a.sitekey = :sitekey AND a.board_no = :board_no';
102	        $params = [
103	            ':sitekey' => $sitekey,
104	            ':board_no' => $boardNo,
105	        ];
106	
107	        if ($categoryNo !== null && $categoryNo > 0) {
108	            $where .= ' AND a.category_no = :category_no';
109	            $params[':category_no'] = $categoryNo;
110	        }
111	
112	        $qTrim = $q !== null ? trim($q) : '';
113	        if ($qTrim !== '') {
114	            $like = '%' . $qTrim . '%';
115	            $where .= ' AND (a.title LIKE :like_title OR a.contents LIKE :like_contents)';
116	            $params[':like_title'] = $like;
117	            $params[':like_contents'] = $like;
118	        }
119	
120	        $db = DB::getInstance();
121	
122	        $countSql = "SELECT COUNT(*) AS cnt FROM nb_board a WHERE {$where}";
123	        $cstmt = $db->prepare($countSql);
124	        foreach ($params as $k => $v) {
125	            $cstmt->bindValue($k, $v);
126	        }
127	        $cstmt->execute();
128	        $totalRows = (int) ($cstmt->fetch(PDO::FETCH_ASSOC)['cnt'] ?? 0);
129	
130	        $totalPages = max(1, (int) ceil($totalRows / $perPage));
131	        if ($page > $totalPages) {
132	            $page = $totalPages;
133	            $offset = ($page - 1) * $perPage;
134	        }
135	
136	        $sql = "SELECT a.no, a.board_no, a.title, a.contents, a.regdate, a.thumb_image, a.is_notice,
137	                       a.category_no, c.name AS category_name
138	                FROM nb_board a
139	                LEFT JOIN nb_board_category c
140	                  ON c.no = a.category_no AND c.board_no = a.board_no AND c.sitekey = a.sitekey
141	                WHERE {$where}
142	                ORDER BY (a.is_notice = 'Y') DESC, a.regdate DESC, a.no DESC
143	                LIMIT :limit OFFSET :offset";
144	
145	        $stmt = $db->prepare($sql);
146	        foreach ($params as $k => $v) {
147	            $stmt->bindValue($k, $v);
148	        }
149	        $stmt->bindValue(':limit', $perPage, PDO::PARAM_INT);
150	        $stmt->bindValue(':offset', $offset, PDO::PARAM_INT);
151	        $stmt->execute();
152	        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC) ?: [];
153	
154	        return [
155	            'rows' => $rows,
156	            'totalRows' => $totalRows,
157	            'totalPages' => $totalPages,
158	            'page' => $page,
159	            'perPage' => $perPage,
160	        ];
161	    }
162	}
