628	    private function normalizeIntegerList($value): array
629	    {
630	        $decoded = $this->decodeJsonValue($value);
631	        if (is_int($decoded)) {
632	            return [$decoded];
633	        }
634	
635	        if (is_string($decoded) && preg_match('/^\d+$/', $decoded) === 1) {
636	            return [(int) $decoded];
637	        }
638	
639	        if (!is_array($decoded)) {
640	            return [];
641	        }
642	
643	        $items = [];
644	        foreach ($decoded as $item) {
645	            if (is_int($item)) {
646	                $items[] = $item;
647	                continue;
648	            }
649	
650	            if (!is_string($item) || preg_match('/^\d+$/', $item) !== 1) {
651	                continue;
652	            }
653	
654	            $items[] = (int) $item;
655	        }
656	
657	        return array_values(array_unique($items));
658	    }
