692	    private function decodeJsonValue($value)
693	    {
694	        if (is_array($value) || is_int($value)) {
695	            return $value;
696	        }
697	
698	        if (!is_string($value)) {
699	            return null;
700	        }
701	
702	        $normalized = trim($value);
703	        if ($normalized === '') {
704	            return null;
705	        }
706	
707	        $decoded = json_decode($normalized, true);
708	        if (json_last_error() === JSON_ERROR_NONE) {
709	            return $decoded;
710	        }
711	
712	        return $normalized;
713	    }
